    const entry = { key: source.key, kind: source.kind };
    if (source.kind === 'text') {
      if (source.initial !== undefined && typeof source.initial !== 'string') {
        throw new TypeError('text initial value must be a string');
      }
      entry.initial = source.initial === undefined ? '' : source.initial;
    } else if (source.kind === 'toggle') {
      if (source.initial !== undefined && typeof source.initial !== 'boolean') {
        throw new TypeError('toggle initial value must be boolean');
      }
      entry.initial = source.initial === undefined ? false : source.initial;
    } else if (source.kind === 'choice') {
      if (!Array.isArray(source.choices) || source.choices.length === 0 ||
          source.choices.some((choice) => typeof choice !== 'string')) {
        throw new TypeError('choices must be a non-empty string array');
      }
      if (new Set(source.choices).size !== source.choices.length) {
        throw new RangeError('choices must be unique');
      }
      entry.choices = source.choices.slice();
      entry.initial = source.initial === undefined ? entry.choices[0] : source.initial;
      if (typeof entry.initial !== 'string') throw new TypeError('choice initial value must be a string');
      if (!entry.choices.includes(entry.initial)) throw new RangeError('invalid choice initial value');
    }
    definitions.push(entry);
  }

  const state = Object.create(null);
  for (const entry of definitions) {
    if (entry.kind !== 'command') state[entry.key] = entry.initial;
  }

  function getState() {
    const snapshot = {};
    for (const entry of definitions) {
      if (entry.kind !== 'command') snapshot[entry.key] = state[entry.key];
    }
    return snapshot;
  }

