    return definitions.find((entry) => entry.key === key);
  }

  function setValue(key, value) {
    const entry = findEntry(key);
    if (!entry || entry.kind === 'command') throw new RangeError('key is not stateful');
    if (entry.kind === 'text' && typeof value !== 'string') throw new TypeError('value must be a string');
    if (entry.kind === 'toggle' && typeof value !== 'boolean') throw new TypeError('value must be boolean');
