'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['createControlBoard']);
const { createControlBoard } = api;

assert.throws(() => createControlBoard(null), TypeError);
assert.throws(() => createControlBoard([]), TypeError);
assert.throws(() => createControlBoard({}), TypeError);
assert.throws(() => createControlBoard({ entries: [null] }), TypeError);
assert.throws(() => createControlBoard({ entries: [{ key: '', kind: 'text' }] }), TypeError);
assert.throws(() => createControlBoard({ entries: [{ key: 'x', kind: 'unknown' }] }), TypeError);
assert.throws(() => createControlBoard({ entries: [{ key: 'x', kind: 'text', initial: 1 }] }), TypeError);
assert.throws(() => createControlBoard({ entries: [{ key: 'x', kind: 'toggle', initial: 0 }] }), TypeError);
assert.throws(() => createControlBoard({ entries: [{ key: 'x', kind: 'choice', choices: [] }] }), TypeError);
assert.throws(() => createControlBoard({ entries: [{ key: 'x', kind: 'choice', choices: ['a', 1] }] }), TypeError);
assert.throws(() => createControlBoard({ entries: [{ key: 'x', kind: 'choice', choices: ['a', 'a'] }] }), RangeError);
assert.throws(() => createControlBoard({ entries: [{ key: 'x', kind: 'choice', choices: ['a'], initial: 'b' }] }), RangeError);
assert.throws(() => createControlBoard({ entries: [{ key: 'x', kind: 'text' }, { key: 'x', kind: 'command' }] }), RangeError);

const blueprint = { entries: [
  { key: 'title', kind: 'text', initial: 'Draft' },
  { key: 'enabled', kind: 'toggle' },
  { key: 'mode', kind: 'choice', choices: ['safe', 'fast'] },
  { key: 'run', kind: 'command' },
  { key: 'note', kind: 'text' }
] };
const board = createControlBoard(blueprint);
assert.deepStrictEqual(Reflect.ownKeys(board).sort(), ['getState', 'invoke', 'setValue']);
assert.deepStrictEqual(board.getState(), { title: 'Draft', enabled: false, mode: 'safe', note: '' });
blueprint.entries[0].initial = 'Mutated';
blueprint.entries[2].choices[0] = 'broken';
blueprint.entries.length = 0;
assert.deepStrictEqual(board.getState(), { title: 'Draft', enabled: false, mode: 'safe', note: '' });

const snapshot = board.setValue('title', 'Ready');
assert.deepStrictEqual(snapshot, { title: 'Ready', enabled: false, mode: 'safe', note: '' });
snapshot.title = 'Corrupted';
assert.deepStrictEqual(board.setValue('enabled', true), { title: 'Ready', enabled: true, mode: 'safe', note: '' });
assert.deepStrictEqual(board.setValue('mode', 'fast'), { title: 'Ready', enabled: true, mode: 'fast', note: '' });
assert.throws(() => board.setValue('title', false), TypeError);
assert.throws(() => board.setValue('enabled', 'true'), TypeError);
assert.throws(() => board.setValue('mode', 1), TypeError);
assert.throws(() => board.setValue('mode', 'other'), RangeError);
assert.throws(() => board.setValue('run', 'x'), RangeError);
assert.throws(() => board.setValue('missing', 'x'), RangeError);
const invoked = board.invoke('run');
assert.deepStrictEqual(invoked, { title: 'Ready', enabled: true, mode: 'fast', note: '' });
invoked.mode = 'corrupt';
assert.deepStrictEqual(board.getState(), { title: 'Ready', enabled: true, mode: 'fast', note: '' });
assert.throws(() => board.invoke('title'), RangeError);
assert.throws(() => board.invoke('missing'), RangeError);
assert.deepStrictEqual(createControlBoard({ entries: [] }).getState(), {});

